"@P|«آموزش رسانه‌ای» یک «رویه» است که «مدیر» را «آمادهٔ» «پرسش سخت» می‌کند. و در «شپاس»، «مصاحبهٔ» مدیرعامل «تبلیغی» بود (اس۲۴) و «پرسش سخت» «نپرسیده» شد. و «نبود آموزش» «دلیل» آن است.",
"@P|**نکتهٔ اول: «پرسش سخت» تمرین می‌خواهد.** «چرا ظرفیت خالی است؟»، «چرا حسابرس مشروط داد؟»، «چرا فروش افت کرد؟». و «سه پرسش» «سه پاسخ» می‌خواهد. و «پاسخ» «تمرین» می‌خواهد.",
"@P|**نکتهٔ دوم: «پل» و «پاسخ».»** «پل» یعنی «پرسش را تکرار کن، بعد پاسخ بده». و «پل» «احترام» می‌سازد. و «پرش» به «پاسخ» «فرار» خوانده می‌شود.",
"@P|**نکتهٔ سوم: «عدد» و «سکوت».** «مدیر» باید «یک عدد» را «حفظ» کند و «بقیه» را «ارجاع» دهد. و «ارجاع» «ضعف» نیست، «سازوکار» است. و «سازوکار» «نوشته» نشده.",
"@P|**نکتهٔ چهارم: «بحران» و «۹۰ ثانیه».** «پیام اول» در «۹۰ ثانیه» «باید» سه چیز بگوید: «چه شد»، «چه کردیم»، «چه می‌شود». و «سه جمله» «تمرین» می‌خواهد.",
"@P|**نکتهٔ پنجم: «آموزش» و «هزینه».** «دو کارگاه» «هزینهٔ» «کم» دارد و «اثر» «بالا». و «اثر» در «بحران بعدی» «سنجیده» می‌شود.",
"@P|**نکتهٔ ششم: «آموزش» و «فرهنگ».** «آموزش» «فقط» «مهارت» نیست؛ «مجوز حرف‌زدن» است. و «مدیر» که «آموزش» دیده «جسارت» «پاسخ» دارد. و «جسارت» «فرهنگ» است.",
"@P|**خوانش ما.** «حلقهٔ صفر» «آموزش» است و «هزینهٔ» آن «کم». و «نبود» آن «هزینهٔ» «بزرگ» دارد. و «شروع» «نشده».",
